const nuevas = $input.all()
  .filter(i => String(i.json.Estado || '').trim().toUpperCase() === 'NUEVO')
  .filter(i => String(i.json.Fuente_URL_o_archivo || '').trim() !== '');
if (!nuevas.length) return [];   // nada que hacer
return nuevas.map(i => ({ json: i.json }));

const fila = $('Una por una').first().json;
const fuente = String(fila.Fuente_URL_o_archivo).trim();
// ¿Es un archivo de Google Drive? (link /file/d/ID, ?id=ID o un ID suelto)
let driveId = null;
const m = fuente.match(/\/d\/([a-zA-Z0-9_-]{20,})/) || fuente.match(/[?&]id=([a-zA-Z0-9_-]{20,})/);
if (m) driveId = m[1];
else if (/^[a-zA-Z0-9_-]{25,}$/.test(fuente)) driveId = fuente;
return [{ json: { row_number: fila.row_number, fuente, es_drive: !!driveId, driveId } }];

const item = $input.first();
const meta = item.binary?.data;
const fail = error => [{ json: { error } }];
if (!meta) return fail('La fuente no devolvió un archivo legible.');
const data = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!data.length || data.length > 12 * 1024 * 1024) return fail('Fuente vacía o superior a 12 MB.');
const mime = meta.mimeType || '';
let kind;
if (data.subarray(0, 1024).includes(Buffer.from('%PDF-'))) kind = 'pdf';
else if (/html/i.test(mime) || /<(?:!doctype html|html|head|body|h1)\b/i.test(data.subarray(0, 4096).toString('utf8'))) kind = 'web';
if (!kind) return fail('Formato sin texto compatible. Usa una página de producto o un PDF con texto seleccionable.');
return [{ json: { kind, content: data.toString('base64') } }];

// Rules applied to evidence from a single product document.
const FAMILIAS = [
  ['Campana industrial', 'Campana LED industrial', /\b(?:campana|high\s*bay)\b/i],
  ['Proyector', 'Proyector LED', /\b(?:proyector|reflector led|floodlight)\b/i],
  ['Otro / especializado', 'Luminaria estanca LED', /\b(?:estanc[ao]|waterproof|vapor tight)\b/i],
  ['Emergencia', 'Luminaria LED de emergencia', /\b(?:emergencia|emergency light)\b/i],
  ['Panel', 'Panel LED', /\bpanel\b/i],
  ['Tubo', 'Tubo LED', /\b(?:tubo|tube)\b/i],
  ['Ampolleta', 'Ampolleta LED', /\b(?:ampolleta|bombilla|bulb)\b/i],
  ['Otro / especializado', 'Luminaria LED', /\b(?:luminaria|luminaire|light fixture)\b/i],
];

const RULES = [
  ['Potencia_W', /^(?:potencia(?: nominal| consumida| electrica)?|consumo de energia|power consumption|wattage)$/],
  ['Flujo_lm', /^(?:flujo luminoso(?: nominal)?|lumens|lumenes|luminous flux)$/],
  ['Eficacia_lm_W', /^(?:eficacia (?:luminica|luminosa)(?: .*?)?|luminous efficacy(?: .*?)?)$/],
  ['CCT_K', /^(?:cct|temperatura de color(?: correlacionada)?(?: \(nominal\))?|correlated color temperature(?: \(nom\))?)$/],
  ['CRI', /^(?:cri|irc|indice de (?:produccion|reproduccion) de color(?: \((?:irc|cri)\))?|color rendering index(?: \(cri\))?)$/],
  ['Tension_V', /^(?:tension(?: de alimentacion)?|voltaje(?: de entrada)?|input voltage)$/],
  ['Frecuencia_Hz', /^(?:frecuencia(?: de linea)?|line frequency)$/],
  ['IP', /^(?:ip|grado de proteccion|codigo de proteccion de ingreso|ingress protection code)$/],
  ['IK', /^(?:ik|resistencia a(?:l|) impactos?|codigo de proteccion de impacto mec\.?|mech\. impact protection code)$/],
  ['Angulo_haz', /^(?:angulo (?:de apertura|del haz)|ampliacion del haz de luz de la luminaria|luminaire light beam spread|beam angle of light source)$/],
  ['Vida_util_h', /^(?:vida (?:util|media)|rated lifetime)$/],
  ['Dimensiones_mm', /^(?:dimensiones|dimensions)(?: \([^)]*\))?$/],
  ['Peso_kg', /^(?:peso(?: neto(?: \(pieza\))?)?|net weight(?: \(piece\))?)$/],
  ['Material', /^(?:material(?: de la carcasa)?|housing material)$/],
  ['Temp_operacion_C', /^(?:temperatura de (?:trabajo|operacion)|rango de temperatura ambiente|ambient temperature range)$/],
  ['Garantia', /^(?:garantia|periodo de garantia|warranty period)$/],
  ['CE', /^(?:marca ce|ce mark)$/],
  ['ENEC', /^(?:marca enec|enec mark)$/],
  ['RoHS', /^(?:cumple con el reglamento rohs de la ue|eu rohs compliant)$/],
  ['codigo', /^(?:sku|codigo de pedido|order code)$/],
  ['x:Factor de potencia', /^(?:factor (?:de )?potencia(?: \(fraccion\))?|power factor(?: \(fraction\))?)$/],
  ['x:Flujo de emergencia', /^(?:flujo de emergencia|emergency luminous flux)$/],
  ['x:Autonomía de emergencia', /^(?:duracion nominal de la iluminacion de emergencia(?: \([^)]*\))?|emergency duration)$/],
  ['x:Regulable', /^(?:regulable|dimmable)$/],
  ['x:Tipo óptico', /^(?:tipo optico|optic type)$/],
  ['x:Conexión', /^(?:conexion|connection)$/],
  ['x:Clase de seguridad', /^(?:clase de proteccion iec|protection class iec)$/],
];

const norm = s => String(s).normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
const keyFor = label => RULES.find(([, pattern]) => pattern.test(norm(label).replace(/:$/, '')))?.[0];
const number = '[+<>≤≥~±-]?\\s*\\d[\\d.,]*';
const measurement = (units, lead = '') =>
  new RegExp('^(?:' + lead + ')(' + number + '(?:(?:\\s*(?:-|–|a|or|o|to|/)\\s*)' + number +
    ')*)(?:\\s*)(' + units + ')\\.?$', 'i');
const valuePatterns = {
  Potencia_W: measurement('W'), Flujo_lm: measurement('lm'), Eficacia_lm_W: measurement('lm\\s*/\\s*W'),
  CCT_K: measurement('K'), Peso_kg: measurement('kg'), Tension_V: measurement('V(?:AC|DC)?', 'AC\\s*|DC\\s*|'),
  Frecuencia_Hz: measurement('Hz'), Vida_util_h: measurement('h(?:rs?\\.?|oras?)?'),
  Temp_operacion_C: measurement('[°º]\\s*C'), Angulo_haz: measurement('°|degree\\(s\\)|grados?'),
  Garantia: measurement('años?|years?|mes(?:es)?|months?'),
  'x:Flujo de emergencia': measurement('lm'),
  'x:Autonomía de emergencia': measurement('h|hora\\(s\\)|horas?|hours?'),
};

function sourceValue(key, raw, brand) {
  const value = String(raw).trim();
  if (!value || value.length > 180 || /https?:|www\.|@|^[-–—]+$|^no aplica$|^not applicable$/i.test(value)) return '';
  if (brand && brand.length >= 3 && norm(value).includes(norm(brand)) && key !== 'codigo') return '';
  if (key in valuePatterns) {
    const match = value.match(valuePatterns[key]);
    if (!match) return '';
    if (['Potencia_W', 'Flujo_lm', 'CCT_K', 'Vida_util_h', 'Peso_kg'].includes(key)) return match[1].trim();
    if (key === 'Angulo_haz') return match[1].trim() + '°';
    return value;
  }
  if (key === 'IP' || key === 'IK') return value.match(new RegExp('^' + key + '\\d{2}\\b', 'i'))?.[0].toUpperCase() || '';
  if (key === 'CRI' || key === 'x:Factor de potencia') return new RegExp('^' + number + '$').test(value) ? value : '';
  if (key === 'Dimensiones_mm') return /^\d[\d.,]*(?:\s*[x×]\s*\d[\d.,]*){1,2}\s*mm$/i.test(value) ? value : '';
  if (['CE', 'ENEC', 'RoHS'].includes(key)) return /^(?:si|yes|marca enec|enec mark)$/.test(norm(value)) ? key : '';
  if (key === 'codigo') return /^[\w.-]{3,40}$/.test(value) ? value : '';
  if (key === 'x:Regulable') return /^(?:si|yes)$/.test(norm(value)) ? 'Sí' : /^no$/i.test(value) ? 'No' : '';
  return value;
}

function extractFicha(doc) {
  const invalid = motivo => ({ es_ficha_valida: false, motivo });
  if (doc.ambiguous) return invalid('La página contiene más de un producto. Ingresa la URL del modelo o su PDF.');
  const title = doc.title || [];
  const family = FAMILIAS.find(([, , pattern]) => title.some(text => pattern.test(text)));
  if (!family) return invalid('No se identificó un producto de iluminación en el título de la fuente.');
  const [familia, nombre_base] = family;
  const brand = doc.brand || '';
  const evidence = new Map();
  const notes = new Set();
  const tables = [...(doc.tables || [])];

  function remember(key, raw, section) {
    if (!key) return;
    const value = sourceValue(key, raw, brand);
    if (!value) return;
    const set = evidence.get(key) || new Map();
    set.set(norm(value), { value, section });
    evidence.set(key, set);
  }

  for (const [label, value, section] of doc.pairs || []) remember(keyFor(label), value, section);
  for (const line of doc.lines || []) {
    const colon = line.indexOf(':');
    if (colon >= 0) remember(keyFor(line.slice(0, colon)), line.slice(colon + 1), 'Campo rotulado');
  }

  // A text PDF keeps table columns in physical reading order via pdftotext -layout.
  const pdfRows = doc.rows || [];
  for (let index = 0; index < pdfRows.length; index++) {
    const row = pdfRows[index];
    const keys = row.map(keyFor);
    const looksLikeHeader = row.length >= 3 && keys.filter(Boolean).length >= 2
      && !keys.some((key, i) => key && !keys[i + 1] && row[i + 1] && valuePatterns[key] && sourceValue(key, row[i + 1], brand));
    if (looksLikeHeader && keys.includes('Potencia_W')) {
      const block = [row];
      const powerCol = keys.indexOf('Potencia_W');
      while (pdfRows[index + 1] && sourceValue('Potencia_W', pdfRows[index + 1][powerCol] || '', brand)) {
        block.push(pdfRows[++index]);
      }
      tables.push(block);
      continue;
    }
    const next = pdfRows[index + 1];
    if (looksLikeHeader && next?.length === row.length && !next.some(keyFor)
      && keys.some((key, i) => valuePatterns[key] && sourceValue(key, next[i], brand))) {
      keys.forEach((key, i) => remember(key, next[i], 'Tabla horizontal del PDF'));
      index++;
      continue;
    }
    for (let cell = 0; cell < row.length; cell++) {
      const key = keys[cell];
      if (key && row[cell + 1] && !keys[cell + 1]) {
        remember(key, row[++cell], 'Columna del PDF');
      } else if (row[cell].includes(':')) {
        const colon = row[cell].indexOf(':');
        remember(keyFor(row[cell].slice(0, colon)), row[cell].slice(colon + 1), 'Campo rotulado del PDF');
      }
    }
  }
  if (doc.code) remember('codigo', doc.code, 'Datos estructurados');

  const common = {};
  for (const [key, values] of evidence) {
    if (values.size === 1) common[key] = values.values().next().value.value;
    else notes.add('Valores contradictorios: ' + key.replace(/^x:/, '') + '.');
  }

  const groups = [];
  for (const [header, ...rows] of tables) {
    const keys = header.map(keyFor);
    // In a clearly marked variant grid with kelvin in this column, "Temperatura" is color.
    keys.forEach((key, i) => {
      if (!key && norm(header[i]) === 'temperatura' && rows.length &&
        rows.every(row => sourceValue('CCT_K', row[i] || '', brand))) keys[i] = 'CCT_K';
    });
    const power = keys.indexOf('Potencia_W');
    if (power < 0 || keys.filter(Boolean).length < 2) continue;
    if (!rows.length || rows.some(row => row.length !== header.length || !sourceValue('Potencia_W', row[power], brand))) {
      return invalid('Se encontró una tabla de variantes con columnas desalineadas. Revisa la fuente.');
    }
    const variants = rows.map(row => Object.fromEntries(keys.flatMap((key, i) =>
      key && sourceValue(key, row[i], brand) ? [[key, sourceValue(key, row[i], brand)]] : [])));
    if (new Set(variants.map(row => JSON.stringify(row))).size !== variants.length) {
      return invalid('La tabla contiene variantes que no se pueden distinguir con los campos reconocidos.');
    }
    groups.push({ variants, keys });
  }
  if (groups.length > 1) return invalid('La fuente contiene varias tablas de variantes sin una clave de unión verificable.');
  if (!groups.length && title.some(line => /\d+\s*W\s*(?:-|–|\/|,)\s*\d+\s*W\b/i.test(line))) {
    return invalid('La fuente anuncia varias potencias pero no se encontró una tabla alineada por modelo.');
  }

  const group = groups[0];
  if (group) {
    for (const key of group.keys.filter(Boolean)) delete common[key];
    delete common.codigo;
  }
  const rows = group ? group.variants.map(row => ({ ...common, ...row })) : [common];
  if (rows.some(row => ['Potencia_W', 'Flujo_lm', 'CCT_K', 'IP', 'Tension_V'].filter(key => row[key]).length < 2)) {
    return invalid('La fuente tiene menos de dos especificaciones eléctricas, lumínicas o de protección verificables.');
  }
  if (/\b(?:atex|cnex|antiexplosiv[oa]|anti-explosiv[oa])\b/i.test(title.join(' '))) {
    notes.add('Verificar por separado los marcados Ex, grados IP y certificados por modelo.');
    delete common.IP;
    for (const row of rows) delete row.IP;
  }
  const variantes = rows.map(row => {
    const specs_extra = Object.entries(row).filter(([key]) => key.startsWith('x:'))
      .map(([key, valor]) => ({ nombre: key.slice(2), valor }));
    const nombre = [nombre_base, row.Potencia_W && row.Potencia_W + ' W',
      row.CCT_K && row.CCT_K + ' K',
      row['x:Autonomía de emergencia'] && familia !== 'Emergencia' && 'con emergencia'].filter(Boolean).join(' ');
    const data = Object.fromEntries(Object.entries(row).filter(([key]) => !key.startsWith('x:') &&
      !['codigo', 'CE', 'ENEC', 'RoHS'].includes(key)));
    return { ...data, nombre, cod_proveedor: row.codigo || '',
      Certificaciones: [row.CE, row.ENEC, row.RoHS].filter(Boolean).join('; '), specs_extra };
  });
  const missing = ['Potencia_W', 'Flujo_lm', 'CCT_K', 'IP'].filter(key => variantes.some(v => !v[key]));
  if (missing.length) notes.add('Sin valor verificable en todos los modelos: ' + missing.join(', ') + '.');
  return {
    es_ficha_valida: true, motivo: '', nombre_base, familia, proveedor: brand, variantes,
    faltantes_y_dudas: [...notes].join(' '),
  };
}


const doc = $input.first().json;
return [{ json: doc.error ? { es_ficha_valida: false, motivo: doc.error } : extractFicha(doc) }];

// Generador de ficha Maxilux en LaTeX. Mismo código que el nodo "Armar LaTeX" del flujo n8n.
// Recibe las filas (una o varias variantes del mismo grupo) y devuelve el .tex.
// Regla central: un campo sin valor NO se imprime; un valor con "VERIFICAR" tampoco.

const CAMPOS = [
  ['Potencia_W', 'Potencia', 'W'],
  ['Flujo_lm', 'Flujo luminoso', 'lm'],
  ['Eficacia_lm_W', 'Eficacia luminosa', 'lm/W'],
  ['CCT_K', 'Temperatura de color', 'K'],
  ['CRI', 'Reproducción cromática (IRC)', ''],
  ['Tension_V', 'Tensión de alimentación', 'V'],
  ['Frecuencia_Hz', 'Frecuencia', 'Hz'],
  ['IP', 'Grado de protección', ''],
  ['IK', 'Resistencia al impacto', ''],
  ['Angulo_haz', 'Ángulo de apertura', ''],
  ['Vida_util_h', 'Vida útil', 'h'],
  ['Dimensiones_mm', 'Dimensiones', 'mm'],
  ['Peso_kg', 'Peso', 'kg'],
  ['Material', 'Material', ''],
  ['Temp_operacion_C', 'Temperatura de operación', '°C'],
  ['Garantia', 'Garantía', ''],
  ['Certificaciones', 'Certificaciones', ''],
];

function esc(s) {
  const map={'\\':'\\textbackslash{}','~':'\\textasciitilde{}','^':'\\textasciicircum{}','<':'\\textless{}','>':'\\textgreater{}','≤':'$\\leq$','≥':'$\\geq$','°':'\\textdegree{}','±':'\\textpm{}','Ф':'\\O{}','Φ':'\\O{}','φ':'\\O{}','×':'$\\times$','Ω':'$\\Omega$','μ':'$\\mu$'};
  return String(s).replace(/[\\&%$#_{}~^<>≤≥°±ФΦφ×Ωμ]/g,c=>map[c]||'\\'+c);
}

const vacio = (v) => v === undefined || v === null || String(v).trim() === '' || /VERIFICAR/i.test(String(v));

function formatear(v, unidad) {
  let s = String(v).trim();
  // Los textos conservan sus separadores originales: 30.000 lm no son 30 lm.
  if (typeof v === 'number') s = v.toLocaleString('es-CL');
  if (unidad) {
    const sinPalabras = s.replace(/\b(a|x)\b/gi, '').replace(/[Øø×]/g, '');
    const yaTieneUnidad = s.toLowerCase().includes(unidad.toLowerCase()) || /[a-z]/i.test(sinPalabras);
    if (!yaTieneUnidad) s += unidad.startsWith('°') ? ' ' + unidad : ' ' + unidad;
  }
  return s;
}

function extras(fila) {
  let obj = {};
  try { obj = typeof fila.Specs_extra_JSON === 'string' && fila.Specs_extra_JSON.trim() ? JSON.parse(fila.Specs_extra_JSON) : (fila.Specs_extra_JSON || {}); } catch (e) { obj = {}; }
  return obj;
}

// Lista ordenada [clave, etiqueta, valorFormateado] solo con lo que existe.
function specs(fila) {
  const out = [];
  for (const [k, et, u] of CAMPOS) if (!vacio(fila[k])) out.push([k, et, formatear(fila[k], u)]);
  for (const [k, v] of Object.entries(extras(fila))) if (!vacio(v)) out.push(['x:' + k, k, String(v)]);
  return out;
}

function nombreGrupo(filas) {
  if (filas.length === 1) return filas[0].Nombre;
  // prefijo común de palabras de los nombres
  const partes = filas.map((f) => String(f.Nombre).split(/\s+/));
  const comun = [];
  for (let i = 0; i < partes[0].length; i++) {
    if (partes.every((p) => p[i] === partes[0][i])) comun.push(partes[0][i]); else break;
  }
  return comun.join(' ') || filas[0].Nombre;
}

function buildTex(filas, cfg) {
  const f0 = filas[0];
  const listas = filas.map(specs);
  const mapa = listas.map((l) => Object.fromEntries(l.map(([k, , v]) => [k, v])));
  const etiquetas = {};
  listas.flat().forEach(([k, et]) => (etiquetas[k] = et));
  const orden = [...new Set(listas.flat().map(([k]) => k))];

  // Comunes: mismo valor en todas las variantes. Variables: difieren o faltan en alguna.
  const comunes = orden.filter((k) => mapa.every((m) => m[k] !== undefined && m[k] === mapa[0][k]));
  const variables = orden.filter((k) => !comunes.includes(k));

  const filasComunes = comunes.map((k, i) =>
    `${i % 2 ? '' : '\\rowcolor{mxgris}'}\\textbf{${esc(etiquetas[k])}} & ${esc(mapa[0][k])} \\\\`).join('\n');

  let tablaVariantes = '';
  if (filas.length > 1) {
    for (let offset = 0; offset < Math.max(variables.length, 1); offset += 3) {
      const cols = variables.slice(offset, offset + 3);
      const count = cols.length + 1;
      const cellWidth = String.raw`>{\raggedright\arraybackslash}p{\dimexpr\linewidth/${count}-2\tabcolsep\relax}`;
      const head = String.raw`\rowcolor{mxazul}\textcolor{white}{\textbf{Código}}${cols.map(k => String.raw` & \textcolor{white}{\textbf{${esc(etiquetas[k])}}}`).join('')} \\`;
      tablaVariantes += String.raw`
\Needspace{5\baselineskip}
\section*{${offset ? 'Variantes disponibles (continuación)' : 'Variantes disponibles'}}
\begin{longtable}{${cellWidth.repeat(count)}}
${head}
\endhead
${filas.map((f, i) => String.raw`${i % 2 ? '' : '\\rowcolor{mxgris}'}${esc(f.SKU_Maxilux)}${cols.map(k => ' & ' + (mapa[i][k] !== undefined ? esc(mapa[i][k]) : '--')).join('')} \\`).join('\n')}
\end{longtable}`;
    }
  }

  const codigo = filas.length > 1 ? `${filas[0].SKU_Maxilux} a ${filas[filas.length - 1].SKU_Maxilux}` : f0.SKU_Maxilux;
  const borrador = !filas.every(f => String(f.Estado).toUpperCase() === 'APROBADO' && f.Revisado_por && f.Fecha_aprobacion);
  const logo = cfg.logo
    ? '\\includegraphics[height=1.1cm]{logo.png}'
    : '{\\fontsize{22}{24}\\selectfont\\bfseries\\color{mxazul}MAXI\\color{mxacento}LUX}';

  return String.raw`\documentclass[10pt,a4paper]{article}
\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage[scaled]{helvet}
\renewcommand{\familydefault}{\sfdefault}
\usepackage[top=1.4cm,bottom=2.2cm,left=1.6cm,right=1.6cm]{geometry}
\usepackage[table]{xcolor}
\usepackage{graphicx,array,longtable,fancyhdr,lastpage,textcomp,needspace}
\definecolor{mxazul}{HTML}{1F3A5F}
\definecolor{mxacento}{HTML}{F2A900}
\definecolor{mxgris}{HTML}{EEF1F5}
\renewcommand{\arraystretch}{1.35}
\setlength{\LTleft}{0pt}
\setlength{\LTright}{0pt}
\setlength{\LTpre}{0pt}
\setlength{\LTpost}{0pt}
\setlength{\emergencystretch}{2em}
\setlength{\parindent}{0pt}
\usepackage{titlesec}
\titleformat{\section}{\large\bfseries\color{mxazul}}{}{0pt}{}[{\color{mxacento}\titlerule[1.2pt]}]
\titlespacing*{\section}{0pt}{14pt}{8pt}
\pagestyle{fancy}\fancyhf{}
\renewcommand{\headrulewidth}{0pt}
\fancyfoot[L]{\scriptsize\color{gray}${esc(cfg.empresa)} · ${esc(cfg.web)}${cfg.contacto ? ' · ' + esc(cfg.contacto) : ''}}
\fancyfoot[R]{\scriptsize\color{gray}${esc(codigo)} · v${esc(f0.Version || 1)} · ${esc(cfg.fecha)} · \thepage/\pageref{LastPage}}
${borrador ? String.raw`\usepackage{eso-pic}
\AddToShipoutPictureBG{\AtPageCenter{\makebox(0,0){\rotatebox{45}{\fontsize{60}{60}\selectfont\color{red!12}\bfseries BORRADOR}}}}` : ''}
\begin{document}
\begin{minipage}[c]{0.5\textwidth}${logo}\end{minipage}%
\begin{minipage}[c]{0.5\textwidth}\raggedleft
{\small\color{gray}FICHA TÉCNICA}\\[1pt]
{\large\bfseries\color{mxazul}${esc(codigo)}}
\end{minipage}
\\[4pt]{\color{mxacento}\rule{\textwidth}{2.5pt}}
\vspace{10pt}

{\LARGE\bfseries\color{mxazul}${esc(nombreGrupo(filas))}}\\[3pt]
{\normalsize\color{gray}${esc(f0.Familia || '')}}

