// ================== Lógica del flujo ==================
const cfg = $('Config').first().json;
const fila = $('Una por una').first().json;
const datos = $input.first().json;
const PREFIJOS = { 'Campana industrial':'CAM', 'Proyector':'PRY', 'Emergencia':'EME', 'Panel':'PAN', 'Tubo':'TUB', 'Ampolleta':'AMP', 'Otro / especializado':'ESP' };

function fallo(msg) { return [{ json: { error: true, row_number: fila.row_number, mensaje: String(msg).slice(0, 500) } }]; }

if (!datos.es_ficha_valida || !datos.variantes?.length) return fallo(datos.motivo || datos.error || 'No se detectaron especificaciones.');

// SKU correlativo sin colisiones (lee la planilla actual)
const prefijo = PREFIJOS[datos.familia] || 'ESP';
const usados = $('Catálogo actual').all().map(i => String(i.json.SKU_Maxilux || ''))
  .filter(s => s.startsWith('MX-' + prefijo + '-')).map(s => parseInt(s.split('-')[2], 10) || 0);
let siguiente = (usados.length ? Math.max(...usados) : 0) + 1;

const hoy = new Date().toLocaleDateString('es-CL', { timeZone: 'America/Santiago', day: '2-digit', month: '2-digit', year: 'numeric' });
const COLS = CAMPOS.map(c => c[0]);
const variantes = datos.variantes;
const grupo = variantes.length > 1 ? 'G-' + prefijo + '-' + String(siguiente).padStart(4, '0') : '';

const filas = variantes.map((v, i) => {
  const extra = {};
  (v.specs_extra || []).forEach(e => { if (e.nombre && e.valor) extra[e.nombre] = e.valor; });
  const f = {
    Estado: 'GENERADO',
    SKU_Maxilux: 'MX-' + prefijo + '-' + String(siguiente++).padStart(4, '0'),
    Grupo_variantes: grupo,
    Nombre: v.nombre || datos.nombre_base,
    Familia: datos.familia,
    Proveedor: datos.proveedor || '',
    Cod_proveedor: v.cod_proveedor || '',
    Fuente_tipo: fila.Fuente_tipo || '',
    Fuente_URL_o_archivo: fila.Fuente_URL_o_archivo,
    Specs_extra_JSON: Object.keys(extra).length ? JSON.stringify(extra) : '',
    Faltantes_y_dudas: datos.faltantes_y_dudas || '',
    Version: 1,
    Fecha_generacion: hoy,
    Generado_por: 'n8n · reglas de extracción',
    Notas_internas: fila.Notas_internas || '',
    Ficha_proveedor: fila.Fuente_URL_o_archivo,
  };
  COLS.forEach(c => f[c] = v[c] === null || v[c] === undefined ? '' : String(v[c]));
  return f;
});

const tex = buildTex(filas,
  { empresa: cfg.EMPRESA, web: cfg.WEB, contacto: cfg.CONTACTO, fecha: hoy, logo: !!cfg.LOGO_URL });
const slug = datos.nombre_base.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_|_$/g, '');
const archivo = (filas.length > 1 ? grupo : filas[0].SKU_Maxilux) + '_' + slug + '_v1';
const bin = await this.helpers.prepareBinaryData(Buffer.from(tex, 'utf8'), archivo + '.tex', 'application/x-tex');

const resources = [{ main: true, content: tex }];
if (cfg.LOGO_URL) resources.push({ path: 'logo.png', url: cfg.LOGO_URL });
return [{ json: { error: false, row_number: fila.row_number, filas, archivo, latex: { compiler: 'pdflatex', resources } }, binary: { tex: bin } }];

const a = $('Armar ficha').first().json;
const pdf = $input.first().json;
const link = 'https://drive.google.com/file/d/' + pdf.id + '/view';
return a.filas.map((f, i) => ({ json: i === 0
  ? { row_number: a.row_number, ...f, Ficha_Maxilux: link }   // la fila original se actualiza
  : { ...f, Ficha_Maxilux: link } }));                         // variantes adicionales se agregan

const encabezado = 'Ingrese URL del producto o ficha externa';
const registradas = new Set($('Fuentes registradas').all().map(i => String(i.json.Fuente_URL_o_archivo || '').trim()));
const nuevas = [];
for (const item of $input.all()) {
  const url = String(item.json[encabezado] || '').trim();
  if (!/^https?:\/\/[^/\s?#@]+(?:[/?#][^\s]*)?$/i.test(url) || registradas.has(url)) continue;
  registradas.add(url);
  nuevas.push({ json: {
    Estado: 'NUEVO',
    Fuente_URL_o_archivo: url,
    Fuente_tipo: /\.pdf(?:[?#]|$)/i.test(url) ? 'PDF' : 'URL',
  } });
}
return nuevas.length ? nuevas : [{ json: {} }];
